import { Component, Element, Event, EventEmitter, h, Host, Prop, State } from '@stencil/core';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';
import { svgAssetsBaseURL } from './svgAssetsBaseURL';

const iconCache = new Map<string, Promise<string>>();

@Component({
  tag: 'groupui-icon',
  styleUrl: 'icon.scss',
  shadow: true,
})
export class Icon {
  @Element() host: HTMLElement;

  /**
   * brand specific name of the referenced svg
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * custom width is supported but it's recommended to use the default sizes. You have to set height too. The smaller value defines both.
   */
  @Prop({ reflect: true }) readonly width: number;

  /**
   * custom height is supported but it's recommended to use the default sizes. You have to set width too. The smaller value defines both.
   */
  @Prop({ reflect: true }) readonly height: number;

  /**
   * sets the alt attribute for the icon
   */
  @Prop({ reflect: true }) readonly alt: string;

  /**
   * sets the title attribute for the icon, which will be shown on hover
   */
  @Prop({ reflect: true, attribute: 'title' }) readonly iconTitle: string;

  /**
   * sets a custom icon source, overrides name
   */
  @Prop({ reflect: true }) readonly src: string;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false, composed: false }) groupuiDidLoad: EventEmitter<void>;

  @State() iconContent: string;

  private readonly svgTitleId = 'iconTitle';

  private ariaAttributes: AriaAttributes;

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.loadAndCacheIcon();
  }

  componentWillUpdate() {
    this.loadAndCacheIcon();
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private async loadAndCacheIcon() {
    const iconUrl = this.getIconUrl();
    if (!iconCache.has(iconUrl)) {
      const iconDataPromise = this.fetchIconData(iconUrl);
      iconCache.set(iconUrl, iconDataPromise);
    }
    const iconData = await iconCache.get(iconUrl);
    this.iconContent = this.addTitleToSvg(iconData) ?? this.getFallbackImage();
  }

  private async fetchIconData(iconUrl: string): Promise<string | undefined> {
    try {
      const iconDataResponse = await fetch(iconUrl);
      if (iconDataResponse.ok) {
        return await iconDataResponse.text();
      }
    } catch (error) {
      console.error(error);
    }
  }

  private getFallbackImage() {
    return `<img src='data:,' alt='${this.alt ? this.alt : this.name}'>`;
  }

  private getIconUrl() {
    let iconSource = document.querySelector('body').getAttribute('data-gui-icon-source');
    if (!iconSource) {
      iconSource = document.querySelector('body').getAttribute('icon-source');
    }
    const basePath = `${svgAssetsBaseURL}/vwgroup`;
    return this.src ?? `${iconSource ?? basePath}/${this.name}.svg`;
  }

  private addTitleToSvg(iconData: string | undefined): string | undefined {
    if (!iconData) {
      return;
    }
    const parser = new DOMParser();
    const iconDom = parser.parseFromString(iconData, 'text/html');
    const svgElement = iconDom.querySelector('svg');
    if (!svgElement) {
      return;
    }
    svgElement.setAttribute('role', 'img');
    if (this.alt || this.iconTitle) {
      svgElement.insertBefore(this.buildTitle(svgElement), svgElement.firstChild);
    } else {
      svgElement.setAttribute('aria-label', this.ariaAttributes['aria-label'] || this.name);
    }
    return iconDom.documentElement.outerHTML;
  }

  private buildTitle(svgElement: SVGSVGElement): HTMLTitleElement {
    svgElement.setAttribute('aria-labelledby', this.svgTitleId);
    const titleElement = document.createElement('title');
    titleElement.textContent = this.iconTitle || this.alt;
    titleElement.id = this.svgTitleId;
    return titleElement;
  }

  private customizeIconSize(data: string): string {
    data = this.customizeIconSizeAttribute(data, 'height');
    data = this.customizeIconSizeAttribute(data, 'width');
    return data;
  }

  private customizeIconSizeAttribute(data: string, attribute: 'height' | 'width'): string {
    if (!this[attribute]) {
      return data;
    }
    return data.replace(new RegExp(`${attribute}="[0-9]*(px)?"`), `${attribute}="${this[attribute]}px"`);
  }

  render() {
    return <Host>{this.iconContent && <div id="content" innerHTML={this.customizeIconSize(this.iconContent)} />}</Host>;
  }
}
